package com.appnexus.platform.security;
import com.appnexus.platform.organization.OrganizationStructure; import java.time.Instant; import java.util.*;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
/** 组织领域 HTTP 入口；权限由权限中心能力校验，组织域只维护结构和任职约束。 */
@RestController @EndpointPolicy(EndpointPolicy.Domain.TENANT_BUSINESS) @RequestMapping("/api/organization/domain") public class OrganizationDomainController {
 private final OrganizationStructure domain; public OrganizationDomainController(OrganizationStructure domain){this.domain=domain;}
 public record TypeInput(String code,String name,Boolean enabled,Long version) {} public record UnitInput(String code,UUID typeId,UUID parentId,String name,Boolean enabled,Long version) {}
 public record MoveInput(UUID parentId,long version) {} public record RelationInput(String relationType,UUID sourceId,UUID targetId) {} public record PositionInput(UUID organizationId,String code,String name,Boolean enabled,Long version) {}
 public record AssignmentInput(UUID memberId,UUID positionId,Instant startsAt,Instant endsAt,Boolean enabled,Long version) {} public record LeaderInput(UUID organizationId,UUID assignmentId,boolean selected) {}
 @EndpointOperation("organization.unit:read") @GetMapping("/types") List<?> types(){return domain.types();} @EndpointOperation("organization.unit:create") @PostMapping("/types") ResponseEntity<?> createType(@RequestBody TypeInput i){return ResponseEntity.status(201).body(domain.createType(code(i.code()),name(i.name())));} @EndpointOperation("organization.unit:update") @PutMapping("/types/{id}") Object updateType(@PathVariable UUID id,@RequestBody TypeInput i){return domain.updateType(id,name(i.name()),required(i.enabled()),required(i.version()));}
 @EndpointOperation("organization.unit:read") @GetMapping("/units") List<?> units(){return domain.units();} @EndpointOperation("organization.unit:create") @PostMapping("/units") ResponseEntity<?> createUnit(@RequestBody UnitInput i){return ResponseEntity.status(201).body(domain.createUnit(code(i.code()),Objects.requireNonNull(i.typeId()),i.parentId(),name(i.name())));} @EndpointOperation("organization.unit:update") @PutMapping("/units/{id}") Object updateUnit(@PathVariable UUID id,@RequestBody UnitInput i){return domain.updateUnit(id,name(i.name()),required(i.enabled()),required(i.version()));} @EndpointOperation("organization.unit:update") @PostMapping("/units/{id}/move") Object move(@PathVariable UUID id,@RequestBody MoveInput i){return domain.moveUnit(id,i.parentId(),i.version());} @EndpointOperation("organization.unit:read") @GetMapping("/units/{id}/impact") Object impact(@PathVariable UUID id){return domain.impact(id);}
 @EndpointOperation("organization.unit:read") @GetMapping("/relations") List<?> relations(){return domain.relations();} @EndpointOperation("organization.unit:create") @PostMapping("/relations") ResponseEntity<?> createRelation(@RequestBody RelationInput i){return ResponseEntity.status(201).body(domain.createRelation(code(i.relationType()),Objects.requireNonNull(i.sourceId()),Objects.requireNonNull(i.targetId())));} @EndpointOperation("organization.unit:delete") @DeleteMapping("/relations/{id}") void deleteRelation(@PathVariable UUID id,@RequestParam long version){domain.deleteRelation(id,version);}
 @EndpointOperation("organization.unit:read") @GetMapping("/positions") List<?> positions(){return domain.positions();} @EndpointOperation("organization.unit:create") @PostMapping("/positions") ResponseEntity<?> createPosition(@RequestBody PositionInput i){return ResponseEntity.status(201).body(domain.createPosition(Objects.requireNonNull(i.organizationId()),code(i.code()),name(i.name())));} @EndpointOperation("organization.unit:update") @PutMapping("/positions/{id}") Object updatePosition(@PathVariable UUID id,@RequestBody PositionInput i){return domain.updatePosition(id,name(i.name()),required(i.enabled()),required(i.version()));}
 @EndpointOperation("organization.unit:read") @GetMapping("/assignments") List<?> assignments(){return domain.assignments();} @EndpointOperation("organization.unit:create") @PostMapping("/assignments") ResponseEntity<?> createAssignment(@RequestBody AssignmentInput i){return ResponseEntity.status(201).body(domain.createAssignment(Objects.requireNonNull(i.memberId()),Objects.requireNonNull(i.positionId()),Objects.requireNonNull(i.startsAt()),i.endsAt()));} @EndpointOperation("organization.unit:update") @PutMapping("/assignments/{id}") Object updateAssignment(@PathVariable UUID id,@RequestBody AssignmentInput i){return domain.updateAssignment(id,i.endsAt(),required(i.enabled()),required(i.version()));}
 @EndpointOperation("organization.unit:read") @GetMapping("/leaders") List<?> leaders(){return domain.leaders();} @EndpointOperation("organization.unit:update") @PutMapping("/leaders") void leader(@RequestBody LeaderInput i){domain.setLeader(Objects.requireNonNull(i.organizationId()),Objects.requireNonNull(i.assignmentId()),i.selected());}
 @EndpointOperation("organization.unit:read") @GetMapping("/members") List<?> members(){return domain.members();}
 private String code(String value){if(value==null||!value.matches("[A-Za-z0-9][A-Za-z0-9_.-]{0,49}"))throw AccountSettingsController.problem(HttpStatus.BAD_REQUEST,"INVALID_CODE","编码须为 1–50 位字母、数字、点、横线或下划线");return value;} private String name(String value){if(value==null||value.isBlank()||value.length()>100)throw AccountSettingsController.problem(HttpStatus.BAD_REQUEST,"INVALID_NAME","名称须为 1–100 个字符");return value.trim();} private boolean required(Boolean value){return Objects.requireNonNull(value,"enabled");} private long required(Long value){return Objects.requireNonNull(value,"version");}
}
